SELECT y.ID, y.NAME, y.CODE, y.PID, y.PATH, y.ISLEAF, y.FROZEN, y.SORT, y.REMARK, y.CREATE_ID, y.CREATE_BY, y.UTC_CREATE, y.MODIFY_ID, y.MODIFY_BY, y.UTC_MODIFY, y.REVISION, s.NAME AS PARENT_NAME FROM sys_organization y LEFT JOIN sys_organization s ON s.ID = y.PID AND s.DELETED = 0
()
AND y.ID = #{q.id,jdbcType=BIGINT}
AND y.NAME LIKE CONCAT('%', #{q.name,jdbcType=VARCHAR}, '%')
AND y.CODE = #{q.code,jdbcType=VARCHAR}
AND y.PID = #{q.pid,jdbcType=BIGINT}
ORDER BY y.SORT ASC, y.UTC_MODIFY DESC

mapper.update:
UPDATE sys_organization
SET SORT = CASE
    WHEN ID = #{id} THEN #{newSort}
    WHEN #{newSort} < #{oldSort}
        AND SORT >= #{newSort}
        AND SORT < #{oldSort} THEN SORT + 1
    WHEN #{newSort} > #{oldSort}
        AND SORT <= #{newSort}
        AND SORT > #{oldSort} THEN SORT - 1
    ELSE SORT
END
WHERE PID = #{pid,jdbcType=BIGINT}
  AND DELETED = 0
  AND (
      (SORT BETWEEN LEAST(#{oldSort}, #{newSort}) AND GREATEST(#{oldSort}, #{newSort}))
      OR ID = #{id}
  )

UPDATE sys_organization
SET FROZEN = #{frozen,jdbcType=INTEGER}
WHERE (
    ID = #{id,jdbcType=BIGINT}

        OR PATH LIKE CONCAT(#{path,jdbcType=VARCHAR}, '/%')

)
AND DELETED = 0
